+Dw+j8/j8/g8Po/P4/P4PD5/Xc//B+jiicsAAAoA
NXT_PAYLOAD
[ -d "$TMP/nexusnet" ] || die "Invalid payload"

say "Installing to $PREFIX ..."
mkdir -p "$PREFIX" "$BIN"
rm -rf "$PREFIX/nexusnet"
cp -a "$TMP/nexusnet" "$PREFIX/nexusnet"

cat > "$BIN/nxt-node" <<WRAP
#!/usr/bin/env python3
import sys
sys.path.insert(0, "$PREFIX")
from nexusnet.cli import main
sys.exit(main())
WRAP
chmod 755 "$BIN/nxt-node"
# Older command names keep working
for alias in nexusnet NexusNet; do ln -sf "$BIN/nxt-node" "$BIN/$alias"; done
cat > "$BIN/panel-tools" <<WRAP
#!/bin/sh
exec "$BIN/nxt-node" panels "\$@"
WRAP
chmod 755 "$BIN/panel-tools"

if [ -z "${NXT_SKIP_APT:-}" ]; then
  install -d -m 700 /etc/nexusnet /var/lib/nexusnet
  # keep an already-configured bot on the new code
  if [ -f /etc/systemd/system/nexusnet-bot.service ]; then
    systemctl daemon-reload || true
    systemctl restart nexusnet-bot 2>/dev/null || true
  fi
fi

ok "NexusNet Node installed. Existing nodes were left untouched."
echo -e "    Open the menu with:  ${Y}nxt-node${N}"
if [ -z "${NXT_NO_LAUNCH:-}" ] && [ -t 0 ]; then
  sleep 1; exec "$BIN/nxt-node"
fi
exit 0
